(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const s = window.__toolboxStore;
  const out = {};
  for (let i = 0; i < 40; i++) {
    await sleep(500);
    if (document.querySelector('.il-modal') || document.querySelector('.pj-toast')) break;
  }
  out.promptShown = !!document.querySelector('.il-modal');
  out.libraryBefore = (await s.listLibrary()).length;
  [...document.querySelectorAll('.il-foot .il-btn')].find((b) => b.textContent.includes('不加入'))?.click();
  await sleep(1500);
  out.libraryAfterSkip = (await s.listLibrary()).length;
  out.toast = document.querySelector('.pj-toast')?.textContent || null;
  out.projectStillThere = (await s.listProjects()).some((p) => p.name.includes('传播测试项目'));
  return JSON.stringify(out);
})()
